import base64
import json
import os
from typing import Any, Dict, Optional

import boto3


def _to_number(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        s = value.strip().replace(",", "")
        if not s:
            return None
        try:
            return float(s)
        except ValueError:
            return None
    if isinstance(value, dict):
        for key in ("Value", "value", "Amount", "amount", "Text", "text"):
            if key in value:
                return _to_number(value[key])
    return None


def _to_str(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, str):
        s = value.strip()
        return s or None
    if isinstance(value, dict):
        for key in ("Text", "text", "Value", "value", "NormalizedValue", "normalizedValue"):
            if key in value and value[key] is not None:
                return _to_str(value[key])
    return str(value)


def _extract_text(field: Any) -> Optional[str]:
    if field is None:
        return None
    if isinstance(field, dict):
        for k in ("Text", "text", "Value", "value", "NormalizedValue", "normalizedValue"):
            if k in field and field[k] is not None:
                return _to_str(field[k])
    return _to_str(field)


def _extract_currency_amount(field: Any) -> Dict[str, Any]:
    if not isinstance(field, dict):
        return {"amount": _to_number(field), "currency": None}
    amount = None
    currency = None
    if "Value" in field:
        amount = _to_number(field["Value"])
    if "value" in field and amount is None:
        amount = _to_number(field["value"])
    for k in ("Currency", "currency", "Code", "code"):
        if k in field and field[k] is not None:
            currency = _to_str(field[k])
            break
    if amount is None and "Text" in field:
        amount = _to_number(field["Text"])
    return {"amount": amount, "currency": currency}


def _normalize_analyze_expense_response(resp: Dict[str, Any]) -> Dict[str, Any]:
    documents = []
    for expense_doc in resp.get("ExpenseDocuments", []) or []:
        doc: Dict[str, Any] = {
            "vendor_name": None,
            "invoice_number": None,
            "invoice_date": None,
            "due_date": None,
            "currency": None,
            "subtotal": None,
            "tax": None,
            "tip": None,
            "total": None,
            "expense_type": None,
            "payment_terms": None,
            "line_items": [],
            "raw": expense_doc,
        }

        summary_fields = expense_doc.get("SummaryFields", []) or []
        for field in summary_fields:
            name = _to_str(field.get("Type", {}).get("Text") or field.get("Type", {}).get("Text")) or ""
            value = field.get("ValueDetection") or {}
            ftype = name.lower()

            if ftype in {"vendor_name", "merchant_name", "supplier_name"}:
                doc["vendor_name"] = _extract_text(value)
            elif ftype in {"invoice_receipt_id", "invoice_id", "invoice_number", "receipt_id"}:
                doc["invoice_number"] = _extract_text(value)
            elif ftype in {"invoice_receipt_date", "due_date", "payment_date"}:
                if ftype == "due_date":
                    doc["due_date"] = _extract_text(value)
                else:
                    doc["invoice_date"] = _extract_text(value)
            elif ftype in {"currency", "payment_currency"}:
                doc["currency"] = _extract_text(value)
            elif ftype in {"subtotal"}:
                doc["subtotal"] = _extract_currency_amount(value)
            elif ftype in {"tax"}:
                doc["tax"] = _extract_currency_amount(value)
            elif ftype in {"tip"}:
                doc["tip"] = _extract_currency_amount(value)
            elif ftype in {"total", "amount_due", "amount_paid"}:
                doc["total"] = _extract_currency_amount(value)
            elif ftype in {"expense_type"}:
                doc["expense_type"] = _extract_text(value)
            elif ftype in {"payment_terms"}:
                doc["payment_terms"] = _extract_text(value)

        for item in expense_doc.get("LineItemGroups", []) or []:
            for line in item.get("LineItems", []) or []:
                line_item: Dict[str, Any] = {
                    "description": None,
                    "quantity": None,
                    "unit_price": None,
                    "amount": None,
                    "raw": line,
                }
                for lf in line.get("LineItemExpenseFields", []) or []:
                    ftype = _to_str(lf.get("Type", {}).get("Text") or lf.get("Type", {}).get("Text")) or ""
                    ftype = ftype.lower()
                    value = lf.get("ValueDetection") or {}

                    if ftype in {"item", "description", "product", "service"}:
                        line_item["description"] = _extract_text(value)
                    elif ftype in {"quantity", "qty"}:
                        line_item["quantity"] = _to_number(_extract_text(value))
                    elif ftype in {"unit_price", "unitprice"}:
                        line_item["unit_price"] = _extract_currency_amount(value)
                    elif ftype in {"line_item_total", "amount", "total"}:
                        line_item["amount"] = _extract_currency_amount(value)

                doc["line_items"].append(line_item)

        documents.append(doc)

    return {
        "documents": documents,
        "raw_response": resp,
    }


def normalize_expense_fields(
    document_bytes: bytes,
    *,
    content_type: str = "application/pdf",
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Normalize expense fields into a standard JSON schema using Amazon Textract AnalyzeExpense.

    Environment:
      - AWS_ACCESS_KEY_ID
      - AWS_SECRET_ACCESS_KEY
      - AWS_SESSION_TOKEN (optional)
      - AWS_DEFAULT_REGION (optional)
    """
    client = boto3.client("textract", region_name=region_name or os.getenv("AWS_DEFAULT_REGION"))

    resp = client.analyze_expense(
        Document={"Bytes": document_bytes},
    )
    return _normalize_analyze_expense_response(resp)


def normalize_expense_fields_from_path(
    file_path: str,
    *,
    content_type: str = "application/pdf",
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    with open(file_path, "rb") as f:
        data = f.read()
    return normalize_expense_fields(data, content_type=content_type, region_name=region_name)
